func TestGetContentFingerprint_ChangesWhenReviewRuleSignalsChange(t *testing.T) {
	t.Parallel()

	db := openTestDB(t)
	ctx := context.Background()

	before, err := db.GetContentFingerprint(ctx)
	require.NoError(t, err)

	row := minimalSessionRow("chk-fingerprint-review", "sess-fingerprint-review", 0)
	row.Facets = facets.SessionFacets{
		ReviewDerivedRules: []facets.ReviewDerivedRule{
			{
				Rule:        "Prefer package-private helpers unless a shared API is required",
				Evidence:    []string{"Review comment asked to avoid exporting a test-only helper"},
				SourceKind:  "pr_comment",
				Strength:    "strong",
				WhyReusable: "This is a recurring org style preference rather than a one-off file fix.",
			},
		},
	}

	err = db.InsertSession(ctx, row)
	require.NoError(t, err)

	after, err := db.GetContentFingerprint(ctx)
	require.NoError(t, err)
	assert.NotEqual(t, before, after)
}

func TestInsertSession_ScoreFields(t *testing.T) {
	t.Parallel()

	db := openTestDB(t)
	ctx := context.Background()

	row := insightsdb.SessionRow{
		CheckpointID:   "chk-scores",
		SessionID:      "sess-scores",
		SessionIndex:   0,
		CreatedAt:      time.Now(),
		OverallScore:   0.75,
		ScoreTokenEff:  0.80,
		ScoreFirstPass: 0.70,
		ScoreFriction:  0.65,
		ScoreFocus:     0.90,
	}

	err := db.InsertSession(ctx, row)
	require.NoError(t, err)

	sessions, err := db.QueryLastNSessions(ctx, 10)
	require.NoError(t, err)
	require.Len(t, sessions, 1)

	got := sessions[0]
	assert.InDelta(t, 0.75, got.OverallScore, 0.001)
	assert.InDelta(t, 0.80, got.ScoreTokenEff, 0.001)
	assert.InDelta(t, 0.70, got.ScoreFirstPass, 0.001)
	assert.InDelta(t, 0.65, got.ScoreFriction, 0.001)
	assert.InDelta(t, 0.90, got.ScoreFocus, 0.001)
}

func TestInsertSession_MultipleSessionsSameCheckpoint(t *testing.T) {
	t.Parallel()

	db := openTestDB(t)
	ctx := context.Background()

	for i := range 3 {
		row := minimalSessionRow("chk-multi", "sess-multi-"+string(rune('A'+i)), i)
		require.NoError(t, db.InsertSession(ctx, row))
	}

	sessions, err := db.QueryLastNSessions(ctx, 10)
